10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
75	
76	const itemsGroupedByType = (items: Item[]): Item[][] => {
77	  const byType = new Map<string, Item[]>();
78	  for (const item of items) {
79	    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
80	  }
81	  return [...byType.values()];
82	};
83	
84	const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;
85	
86	const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
87	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  itemsGroupedByType(items).reduce(
91	    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
92	    0,
93	  );
94	
95	const withFirstInsuranceSurcharge = (policyBase: number): number =>
96	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
97	
98	const roundInMHPCOsFavor = Math.ceil;
99	
100	const CURSE_SURCHARGE = 0.5;
101	
102	const itemSurcharges = (item: Item): number =>
103	  item.cursed === true ? itemBasePremium(item) * CURSE_SURCHARGE : 0;
104	
105	const totalItemSurcharges = (items: Item[]): number =>
106	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
107	
108	const quotePremium = (items: Item[]): number =>
109	  roundInMHPCOsFavor(
110	    withFirstInsuranceSurcharge(policyBasePremium(items)) +
111	      totalItemSurcharges(items) +
112	      PROCESSING_FEE,
113	  );
114	
115	const runStep = (step: Step): StepResult => {
116	  if (step.op === "quote") {
117	    return { premium: quotePremium(step.items) };
118	  }
119	  throw new Error(`Unsupported step: ${step.op}`);
120	};
121	
122	export const runScenario = (scenario: Scenario): ScenarioResult => ({
123	  results: scenario.steps.map(runStep),
124	});
